export interface EventCommunicationProps { eventId: string; eventTitle: string; organizationName: string; modules: EventModuleFlags }
export interface CommunicationManagerProps extends EventCommunicationProps { initialTicketId?: string }
export interface LogisticsManagerProps extends EventCommunicationProps { participants?: readonly { userId: string; label: string }[] }
const statusText: Record<TicketStatus, string> = { open: "等待答复", in_progress: "正在处理", answered: "已答复", closed: "已关闭" };
const voucherState = { available: "可使用", exhausted: "已用完", expired: "已过期", revoked: "已撤销" };
const publicPath = (eventId: string) => `/competitions/${encodeURIComponent(eventId)}`;
const staffPath = (eventId: string) => `/organizer/events/${encodeURIComponent(eventId)}`;
const denied = (error: unknown) => error instanceof ApiError && [401, 403].includes(error.status);

function useBoundary(...errors: (Error | null)[]) {
  const [locked, setLocked] = useState(false);
  const lock = useCallback(() => setLocked(true), []);
  const inaccessible = errors.some(denied);
  useEffect(() => { if (inaccessible) lock(); }, [inaccessible, lock]);
  useEffect(() => { window.addEventListener("hackathon:unauthenticated", lock); return () => window.removeEventListener("hackathon:unauthenticated", lock); }, [lock]);
  return { locked, lock };
}
function useAction(lock?: () => void) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const alive = useRef(true);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);
  async function run(task: () => Promise<unknown>, success: string, onSuccess?: () => void | Promise<void>) {
    if (busy) return;
    setBusy(true); setError(""); setNotice("");
    try { await task(); if (!alive.current) return; await onSuccess?.(); if (alive.current) setNotice(success); }
    catch (reason) { if (!alive.current) return; if (denied(reason)) lock?.(); setError(message(reason)); }
    finally { if (alive.current) setBusy(false); }
  }
  return { busy, error, notice, run };
}
type Action = ReturnType<typeof useAction>;
function Feedback({ action, reload }: { action: Action; reload?: () => Promise<void> }) { return <>{action.error && <div role="alert" className={styles.error}><p>{action.error} 输入已保留。</p>{reload && <button type="button" disabled={action.busy} onClick={() => void reload()}>重新读取当前记录，输入保留</button>}</div>}{action.notice && <p role="status" className={styles.success}>{action.notice}</p>}</>; }
function DraftHint({ active, text = "本页有尚未提交的输入。切换赛事前请先提交或放弃；切换后本地输入会清除。" }: { active: boolean; text?: string }) {
  useEffect(() => { if (!active) return; const warn = (event: BeforeUnloadEvent) => { event.preventDefault(); event.returnValue = ""; }; window.addEventListener("beforeunload", warn); return () => window.removeEventListener("beforeunload", warn); }, [active]);
  return active ? <p className={styles.draftHint} data-unsaved="true">{text}</p> : null;
}
function ParticipantChoices({ participants, listId }: { participants?: LogisticsManagerProps["participants"]; listId: string }) {
  return participants?.length ? <datalist id={listId}>{participants.map(person => <option key={person.userId} value={person.userId}>{person.label}</option>)}</datalist> : null;
}
function ParticipantHint({ participants }: { participants?: LogisticsManagerProps["participants"] }) { return <p className={styles.muted}>{participants?.length ? "输入姓名提示或从当前赛事报名名单中选择对应账号。" : "请从当前赛事已通过报名名单复制账号编号；勿填写姓名、电话或邮箱代替。"}</p>; }
function AnnouncementHistory({ path }: { path: string }) {
  const [open, setOpen] = useState(false); const history = useApi<AnnouncementView[]>(open ? `${path}/versions` : null);
  return <details className={styles.details} onToggle={event => setOpen(event.currentTarget.open)}><summary>查看通知版本与依据</summary>{open && <LoadState query={history}>{history.data?.map(item => <article className={styles.preview} key={item.revision}><h4>版本 {item.revision} · {item.title}</h4><p className={styles.muted}>{item.status === "published" ? "已发布版本" : item.status === "draft" ? "内部草稿" : "撤回记录"} · {dateText(item.updatedAt)}</p><Deadline value={item.dueAt} /><p className={styles.pre}>{item.body}</p><p className={styles.impact}>影响：{item.impact || "未填写"}</p></article>)}</LoadState>}</details>;
}
function LoadState({ query, empty, children }: { query: { data?: unknown; loading: boolean; error: Error | null; reload: () => Promise<void> }; empty?: boolean; children: ReactNode }) {
  const hasData = query.data !== undefined && query.data !== null;
  const failure = query.error && <div className={styles.error} role="alert"><p>{message(query.error)}{hasData ? " 当前仍显示上次读取内容，编辑输入已保留，请重新读取后核对。" : ""}</p><button type="button" onClick={() => void query.reload()}>重新读取</button></div>;
  const progress = query.loading && <p className={styles.muted} role="status">正在读取当前赛事…</p>;
  if (!hasData && (query.error || query.loading)) return <>{failure}{progress}</>;
  return <>{failure}{progress}{empty ? <p className={styles.empty}>暂时没有记录，请留意本页更新。</p> : children}</>;
}
function Identity({ props, role, next }: { props: EventCommunicationProps; role: string; next: string }) {
  return <header className={styles.identity}><div><p className={styles.eyebrow}>{props.organizationName} · {role}</p><h2>{props.eventTitle}</h2></div><p className={styles.next}><strong>下一步</strong>{next}</p></header>;
}
function AccessNotice({ eventId }: { eventId: string }) {
  return <div className={styles.empty}><p>登录或权限已变化，私人内容和表单已清除。请重新登录后打开此赛事。</p><a href={`/login?returnTo=${encodeURIComponent(`${publicPath(eventId)}/help`)}`}>登录并返回此赛事</a></div>;
}
function Deadline({ value }: { value: string | null }) { return value ? <p className={styles.deadline}>请在 {dateText(value)} 前处理</p> : null; }
function TicketHistory({ ticket }: { ticket: TicketView }) {
  return <><p className={styles.pre}>{ticket.question}</p><p className={styles.muted}>服务器记录版本 {ticket.revision} · 发起于 {dateText(ticket.createdAt)} · 更新于 {dateText(ticket.updatedAt)}</p>
    <ol className={styles.replies}>{ticket.replies.map(reply => <li key={reply.id}><strong>{reply.role === "staff" ? "主办方答复" : "本人补充"}</strong><span className={styles.muted}> · {dateText(reply.createdAt)}</span><p className={styles.pre}>{reply.body}</p></li>)}</ol></>;
}
function FaqPreviewBody({ preview }: { preview: NonNullable<TicketView["faqPreview"]> }) {
  return <div className={styles.preview}><h4>{preview.title}</h4><p className={styles.pre}>{preview.question}</p><p className={styles.pre}>{preview.answer}</p><p className={styles.muted}>公开预览版本 {preview.revision} · 整理于 {dateText(preview.proposedAt)}</p></div>;
}

export function EventCommunicationPanel(props: EventCommunicationProps) { return <CommunicationInner key={props.eventId} {...props} />; }
function CommunicationInner(props: EventCommunicationProps) {
  const base = publicPath(props.eventId);
  const announcements = useApi<AnnouncementView[]>(`${base}/announcements`);
  const tickets = useApi<TicketView[]>(`${base}/help-tickets`);
  const faqs = useApi<PublicFaq[]>(`${base}/faq`);
  const boundary = useBoundary(tickets.error);
  const action = useAction(boundary.lock);
  const ownTickets = (tickets.data ?? []).filter(ticket => ticket.own);
  const publicTickets = (tickets.data ?? []).filter(ticket => !ticket.own && ticket.visibility === "public");
  const unread = (announcements.data ?? []).filter(item => !item.read).length;
  return <section className={styles.panel} aria-label="赛事公告与求助"><Identity props={props} role="选手沟通区" next={unread ? `先查看 ${unread} 条未读官方通知。` : "查看答复；需要帮助时，向主办方发一个明确的问题。"} />
    <section className={styles.section}><h3>官方通知</h3><p className={styles.muted}>已读只记录当前公告版本，更新后请再次查看。站内通知与邮件投递分别记录。</p>
      <LoadState query={announcements} empty={announcements.data?.length === 0}>{announcements.data?.map(item => <article key={item.id} className={`${styles.card} ${item.important ? styles.important : ""}`}><div className={styles.cardHead}><h4>{item.title}</h4><span className={styles.badge}>{item.important ? "重要通知" : "官方通知"} · {item.read ? "已读" : "未读"}</span></div><Deadline value={item.dueAt} /><p className={styles.pre}>{item.body}</p><p className={styles.impact}><strong>对你的影响：</strong>{item.impact}</p><p className={styles.muted}>版本 {item.revision} · 发布于 {dateText(item.publishedAt)}</p><AnnouncementHistory path={`${base}/announcements/${encodeURIComponent(item.id)}`} />{!item.read && !boundary.locked && <button type="button" disabled={action.busy} onClick={() => void action.run(() => api(`${base}/announcements/${encodeURIComponent(item.id)}/read`, { method: "POST", body: { revision: item.revision } }), "当前版本已标为已读。", announcements.reload)}>我已阅读本次通知</button>}</article>)}</LoadState><Feedback action={action} reload={announcements.reload} />
    </section>
    <section className={styles.section}><h3>我的问题与答复</h3>{boundary.locked ? <AccessNotice eventId={props.eventId} /> : <><LoadState query={tickets}>{ownTickets.length ? ownTickets.map(ticket => <OwnTicket key={ticket.id} ticket={ticket} base={base} reload={tickets.reload} reloadFaq={faqs.reload} lock={boundary.lock} />) : <p className={styles.empty}>你还没有发起问题。报名通过后，可以在下面向主办方求助。</p>}</LoadState><NewTicket base={base} reload={tickets.reload} lock={boundary.lock} /></>}</section>
    <section className={styles.section}><h3>公开问答</h3><LoadState query={faqs}>{faqs.data?.length ? faqs.data.map(faq => <article className={styles.card} key={faq.id}><h4>{faq.title}</h4><p className={styles.pre}>{faq.question}</p><p className={styles.answer}>{faq.answer}</p><p className={styles.muted}>主办方整理 · 原作者已确认公开 · {dateText(faq.publishedAt)}</p></article>) : <p className={styles.empty}>主办方还没有发布常见问题答复。</p>}</LoadState>
      {publicTickets.length > 0 && <details className={styles.details}><summary>查看其他公开问题（{publicTickets.length}）</summary>{publicTickets.map(ticket => <article className={styles.card} key={ticket.id}><div className={styles.cardHead}><h4>公开问题</h4><span className={styles.badge}>{statusText[ticket.status]}</span></div><TicketHistory ticket={ticket} /></article>)}</details>}
    </section>
  </section>;
}
function NewTicket({ base, reload, lock }: { base: string; reload: () => Promise<void>; lock: () => void }) {
  const [question, setQuestion] = useState(""); const [visibility, setVisibility] = useState<"public" | "private">("private");
  const action = useAction(lock);
  const submit = (event: FormEvent) => { event.preventDefault(); void action.run(() => api(`${base}/help-tickets`, { method: "POST", body: { question, visibility } }), "问题已发给当前赛事主办方。", async () => { setQuestion(""); await reload(); }); };
  return <form className={styles.form} onSubmit={submit}><h4>向主办方提问</h4><Field label="谁可以看到？" hint="私人求助只有本人和本场沟通人员可见；公开问题任何访客可见，请按内容选择。"><select value={visibility} onChange={event => setVisibility(event.target.value as "public" | "private")}><option value="private">私人求助：仅本人和本赛事沟通人员</option><option value="public">公开问题：所有访客可见</option></select></Field><p className={styles.muted}>{visibility === "private" ? "适合涉及个人安排的问题。以后整理为公开问答时，需要你预览同意。" : "问题和后续答复将公开，请不要填写电话、证件、房号或私人材料。"}</p><Field label="你希望解决什么？" hint="必填。说明遇到什么情况、希望确认什么，例如“我是首次参赛，请问报名通过后是否可以现场找队友？”"><textarea required maxLength={6000} rows={4} value={question} onChange={event => setQuestion(event.target.value)} placeholder="说明遇到的情况，以及希望主办方确认的事项。" /></Field><DraftHint active={Boolean(question.trim())} /><button className={styles.primary} disabled={action.busy} type="submit">{action.busy ? "正在发送…" : visibility === "private" ? "发送私人求助" : "发布公开问题"}</button><Feedback action={action} reload={reload} /></form>;
}
function OwnTicket({ ticket, base, reload, reloadFaq, lock }: { ticket: TicketView; base: string; reload: () => Promise<void>; reloadFaq: () => Promise<void>; lock: () => void }) {
  const [reply, setReply] = useState(""); const [consent, setConsent] = useState(false); const action = useAction(lock);
  useEffect(() => setConsent(false), [ticket.faqPreview?.revision]);
  return <article className={styles.card}><div className={styles.cardHead}><h4>{ticket.visibility === "private" ? "私人求助" : "公开问题"}</h4><span className={styles.badge}>{statusText[ticket.status]}</span></div><TicketHistory ticket={ticket} />
    {ticket.status !== "closed" && <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${base}/help-tickets/${encodeURIComponent(ticket.id)}/replies`, { method: "POST", body: { body: reply, expectedRevision: ticket.revision } }), "补充已发送。", async () => { setReply(""); await reload(); }); }}><Field label="补充说明" hint="必填。补充该问题的新情况或缺少的信息，内容会按原求助范围发送。"><textarea required maxLength={6000} rows={2} value={reply} onChange={event => setReply(event.target.value)} /></Field><button type="submit" disabled={action.busy}>{action.busy ? "正在发送…" : "发送补充"}</button></form>}
    {ticket.faqPreview && <section className={styles.consent}><h4>{ticket.faqPreview.consentedAt ? "你已同意的公开答复" : "请检查主办方整理的公开预览"}</h4><FaqPreviewBody preview={ticket.faqPreview} />{ticket.faqPreview.consentedAt ? <p className={styles.success}>此版本已于 {dateText(ticket.faqPreview.consentedAt)} 经你同意公开。</p> : <><p>以下内容将成为任何访客可见的问答。请确认正文不会暴露你不愿公开的信息；内容本身仍可能识别身份。</p><label className={styles.check}><input type="checkbox" checked={consent} onChange={event => setConsent(event.target.checked)} />我已逐字查看此版本，同意公开这些文字</label><button className={styles.primary} type="button" disabled={!consent || action.busy} onClick={() => void action.run(() => api(`${base}/help-tickets/${encodeURIComponent(ticket.id)}/publish-consent`, { method: "POST", body: { previewRevision: ticket.faqPreview!.revision, expectedRevision: ticket.revision, consent: true } }), "你确认的预览已公开。", async () => { setConsent(false); await Promise.all([reload(), reloadFaq()]); })}>同意并公开此版本</button><p className={styles.muted}>不勾选即可继续保留原有求助范围。需要调整时，可在上方补充说明。</p></>}</section>}<DraftHint active={Boolean(reply.trim() || consent)} /><Feedback action={action} reload={reload} />
  </article>;
}

export function CommunicationManager(props: CommunicationManagerProps) { return <CommunicationManagerInner key={props.eventId} {...props} />; }
function CommunicationManagerInner(props: CommunicationManagerProps) {
  const base = staffPath(props.eventId); const tickets = useApi<TicketView[]>(`${base}/help-tickets`); const announcements = useApi<Announcement[]>(`${base}/announcements`);
  const boundary = useBoundary(tickets.error, announcements.error); const [selected, setSelected] = useState(props.initialTicketId ?? "");
  const current = tickets.data?.find(item => item.id === selected) ?? tickets.data?.find(item => item.status === "open" || item.status === "in_progress") ?? tickets.data?.[0];
  const pending = (tickets.data ?? []).filter(ticket => ["open", "in_progress"].includes(ticket.status));
  return <section className={styles.panel}><Identity props={props} role="赛事沟通人员" next={pending.length ? `先答复 ${pending.length} 个待处理问题。` : "处理选手问题，必要时发布有明确影响和期限的官方通知。"} />
    {boundary.locked ? <AccessNotice eventId={props.eventId} /> : <><section className={styles.section}><div className={styles.cardHead}><h3>待回复与所有问题</h3><span className={styles.badge}>{pending.length} 个待处理</span></div><LoadState query={tickets}>{tickets.data?.length ? <div className={styles.worklist}><nav aria-label="选择问题" className={styles.ticketList}>{tickets.data.map(ticket => <button type="button" className={current?.id === ticket.id ? styles.selected : ""} onClick={() => setSelected(ticket.id)} key={ticket.id}><span>{ticket.visibility === "private" ? "私人求助" : "公开问题"} · {statusText[ticket.status]}</span><strong>{ticket.question.slice(0, 90)}</strong><small>{dateText(ticket.updatedAt)}</small></button>)}</nav>{current && <ManagedTicket key={current.id} ticket={current} base={base} reload={tickets.reload} lock={boundary.lock} />}</div> : <p className={styles.empty}>本赛事还没有问题。收到后会出现在这里。</p>}</LoadState></section>
      <section className={styles.section}><h3>官方通知</h3><AnnouncementEditor base={base} reload={announcements.reload} lock={boundary.lock} /><LoadState query={announcements}>{announcements.data?.map(item => <ManagedAnnouncement key={item.id} item={item} base={base} reload={announcements.reload} lock={boundary.lock} />)}</LoadState></section></>}
  </section>;
}
function ManagedTicket({ ticket, base, reload, lock }: { ticket: TicketView; base: string; reload: () => Promise<void>; lock: () => void }) {
  const [reply, setReply] = useState(""); const [status, setStatus] = useState<TicketStatus>(ticket.status);
  const [title, setTitle] = useState(ticket.faqPreview?.title ?? ""); const [question, setQuestion] = useState(ticket.faqPreview?.question ?? ticket.question); const [answer, setAnswer] = useState(ticket.faqPreview?.answer ?? "");
  const action = useAction(lock); const path = `${base}/help-tickets/${encodeURIComponent(ticket.id)}`;
  useEffect(() => setStatus(ticket.status), [ticket.status]);
  return <article className={styles.card}><div className={styles.cardHead}><h4>{ticket.visibility === "private" ? "私人求助：仅授权人员和本人可见" : "公开问题"}</h4><span className={styles.badge}>{statusText[ticket.status]}</span></div><TicketHistory ticket={ticket} /><DraftHint active={Boolean(reply.trim() || title !== (ticket.faqPreview?.title ?? "") || question !== (ticket.faqPreview?.question ?? ticket.question) || answer !== (ticket.faqPreview?.answer ?? ""))} />
    {ticket.status !== "closed" && <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${path}/replies`, { method: "POST", body: { body: reply, expectedRevision: ticket.revision } }), "正式答复已发送给选手。", async () => { setReply(""); await reload(); }); }}><Field label="给选手的正式答复" hint="必填。直接回答问题，给出明确操作或负责渠道，例如“请于周五前在本场队伍页申请加入，工作人员可协助介绍”。"><textarea required maxLength={6000} rows={4} value={reply} onChange={event => setReply(event.target.value)} /></Field><button className={styles.primary} type="submit" disabled={action.busy}>{action.busy ? "正在发送…" : "发送答复"}</button></form>}
    <form className={styles.inlineForm} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${path}/status`, { method: "PATCH", body: { status, expectedRevision: ticket.revision } }), "处理状态已更新。", reload); }}><Field label="处理状态" hint="正在处理表示仍需跟进；已答复表示已有答复；已关闭停止后续补充。状态变化请与实际处理一致。"><select value={status} onChange={event => setStatus(event.target.value as TicketStatus)}>{Object.entries(statusText).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></Field><button type="submit" disabled={action.busy || status === ticket.status}>更新状态</button></form>
    <details className={styles.details}><summary>整理为公开问答，发给原作者确认</summary><p>先去除姓名、联系方式、住宿和个人材料，再请原作者检查。收到同意前不会发布。</p>{ticket.faqPreview && <><FaqPreviewBody preview={ticket.faqPreview} /><p className={styles.muted}>{ticket.faqPreview.consentedAt ? "原作者已同意此版本。新预览仍需重新同意。" : "此预览正在等待原作者同意。"}</p></>}
      <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${path}/faq-preview`, { method: "POST", body: { title, question, answer, expectedRevision: ticket.revision } }), "预览已发给原作者，等待本人同意。", reload); }}><Field label="公开标题" hint="必填。写通用问题标题，例如“第一次参赛如何找队友”，避免出现私人身份信息。"><input required maxLength={200} value={title} onChange={event => setTitle(event.target.value)} /></Field><Field label="公开问题" hint="必填。整理成其他选手也能理解的问题，删除姓名、电话、房号等私人内容；原作者同意后才公开。"><textarea required maxLength={6000} rows={3} value={question} onChange={event => setQuestion(event.target.value)} /></Field><Field label="公开答复" hint="必填。填写面向所有选手的通用解答，不放私人安排；先发预览给原作者确认。"><textarea required maxLength={6000} rows={4} value={answer} onChange={event => setAnswer(event.target.value)} /></Field><button type="submit" disabled={action.busy}>发送公开预览</button></form></details><Feedback action={action} reload={reload} />
  </article>;
}
function AnnouncementEditor({ base, reload, lock, initial }: { base: string; reload: () => Promise<void>; lock: () => void; initial?: Announcement }) {
  const [title, setTitle] = useState(initial?.title ?? ""); const [body, setBody] = useState(initial?.body ?? ""); const [impact, setImpact] = useState(initial?.impact ?? ""); const [important, setImportant] = useState(initial?.important ?? false); const [due, setDue] = useState(localInput(initial?.dueAt)); const action = useAction(lock);
  async function save(publish: boolean) {
    await action.run(async () => { const dueAt = due ? chinaInstant(due) : null; await api(`${base}/announcements${publish ? "" : "/draft"}`, { method: "POST", body: { ...(initial ? { announcementId: initial.id } : {}), expectedRevision: initial?.revision ?? 0, title, body, impact, important, dueAt } }); }, publish ? "官方通知已发布。请在下方核对站内与邮件状态。" : "通知草稿已保存，尚未公开。", async () => { if (!initial) { setTitle(""); setBody(""); setImpact(""); setImportant(false); setDue(""); } await reload(); });
  }
  return <form className={styles.form} onSubmit={event => { event.preventDefault(); void save(true); }}><h4>{initial ? `编辑通知 · 当前版本 ${initial.revision}` : "发布一条通知"}</h4><Field label="通知标题" hint="必填。概括这次提醒，例如“周六 9 点签到，请携带报名确认信息”。"><input required maxLength={200} value={title} onChange={event => setTitle(event.target.value)} /></Field><Field label="正文" hint="必填。写清时间、地点、具体安排和联系渠道；发布后作为本场官方通知展示。"><textarea required maxLength={12000} rows={4} value={body} onChange={event => setBody(event.target.value)} /></Field><Field label="选手需要做什么、有什么影响？" hint="正式发布必填，保存草稿可空。明确行动和受影响的人，例如“线下选手请提前 15 分钟到达；已签到者无需重复操作”。"><textarea required maxLength={1000} rows={2} value={impact} onChange={event => setImpact(event.target.value)} /></Field><label className={styles.check}><input type="checkbox" checked={important} onChange={event => setImportant(event.target.checked)} />重要通知，提醒选手再次阅读</label><Field label="处理期限（北京时间 UTC+8，选填）" hint="选填。选手需要完成操作的最后时间；无期限可留空。这不是通知发布的定时发送时间。"><input type="datetime-local" value={due} onChange={event => setDue(event.target.value)} /></Field><div className={styles.actions}><button className={styles.primary} type="submit" disabled={action.busy}>{action.busy ? "正在保存…" : "确认发布官方通知"}</button><button type="button" disabled={action.busy} onClick={() => void save(false)}>先保存草稿</button></div><DraftHint active={title !== (initial?.title ?? "") || body !== (initial?.body ?? "") || impact !== (initial?.impact ?? "") || important !== (initial?.important ?? false) || due !== localInput(initial?.dueAt)} /><Feedback action={action} reload={reload} /></form>;
}
function ManagedAnnouncement({ item, base, reload, lock }: { item: Announcement; base: string; reload: () => Promise<void>; lock: () => void }) {
  const action = useAction(lock);
  return <article className={`${styles.card} ${item.important ? styles.important : ""}`}><div className={styles.cardHead}><h4>{item.title}</h4><span className={styles.badge}>{item.status === "published" ? "已发布" : item.status === "draft" ? "草稿" : "已撤回"} · 版本 {item.revision}</span></div><Deadline value={item.dueAt} /><p className={styles.pre}>{item.body}</p><p className={styles.impact}>{item.impact}</p><p className={styles.muted}>通知渠道：{item.notification.state === "queued" ? "邮件已入队，实际投递待确认" : "仅站内，邮件通知未配置"}</p><AnnouncementHistory path={`${base}/announcements/${encodeURIComponent(item.id)}`} />{item.id.startsWith(`rule-change:${item.eventId}:`) ? <p className={styles.muted}>正式规则发布记录。需要调整时，请在比赛设置中发布新规则版本。</p> : <><details className={styles.details}><summary>编辑并形成新版本</summary><AnnouncementEditor initial={item} base={base} reload={reload} lock={lock} /></details>{item.status !== "withdrawn" && <details className={styles.details}><summary>撤回此通知</summary><p>撤回后不再作为当前官方通知展示，历史版本仍保留。</p><button type="button" disabled={action.busy} onClick={() => void action.run(() => api(`${base}/announcements/${encodeURIComponent(item.id)}/withdraw`, { method: "POST", body: { expectedRevision: item.revision } }), "通知已撤回。", reload)}>确认撤回</button></details>}</>}<Feedback action={action} reload={reload} /></article>;
}

function timeText(value: string, timezone: string) { try { return new Intl.DateTimeFormat("zh-CN", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23", timeZoneName: "shortOffset" }).format(new Date(value)); } catch { return dateText(value); } }
function ScheduleCards({ value }: { value: PublishedSchedule }) {
  return <><p className={styles.timezone}>赛事时区：{value.timezone} · 发布版本 {value.revision ?? "未发布"}</p>{value.impact && <p className={styles.impact}><strong>本次更新影响：</strong>{value.impact}</p>}{value.items.length ? <ol className={styles.schedule}>{value.items.map(item => <li className={styles.card} key={item.id}><h4>{item.title}</h4><p className={styles.deadline}>{timeText(item.startsAt, value.timezone)} → {timeText(item.endsAt, value.timezone)}</p><p>地点：{item.location}</p><p className={styles.muted}>适用范围：{item.audience === "all" ? "所有访客" : item.audience === "participants" ? "本赛事报名通过的选手" : "指定人员"}</p></li>)}</ol> : <p className={styles.empty}>尚无适用于你的已发布行程，请留意官方通知。</p>}</>;
}
export function EventSchedulePanel(props: EventCommunicationProps) { return <ScheduleInner key={props.eventId} {...props} />; }
function ScheduleInner(props: EventCommunicationProps) {
  const [showHistory, setShowHistory] = useState(false); const schedule = useApi<PublishedSchedule>(props.modules.schedule || showHistory ? `${publicPath(props.eventId)}/schedule` : null);
  return <section className={styles.panel}><Identity props={props} role="赛事行程" next="按下列时间和地点准备；行程有更新时请查看影响说明。" />{props.modules.schedule ? <LoadState query={schedule}>{schedule.data && <ScheduleCards value={schedule.data} />}</LoadState> : <><p className={styles.empty}>行程功能目前关闭，请查看官方通知。已发布的历史仍保留。</p><details className={styles.details} onToggle={event => setShowHistory(event.currentTarget.open)}><summary>查看适用于我的已发布行程历史</summary>{showHistory && <LoadState query={schedule}>{schedule.data && <ScheduleCards value={schedule.data} />}</LoadState>}</details></>}</section>;
}

export function ScheduleManager(props: EventCommunicationProps) { return <ScheduleManagerInner key={props.eventId} {...props} />; }
function ScheduleManagerInner(props: EventCommunicationProps) {
  const [showHistory, setShowHistory] = useState(false); const base = staffPath(props.eventId); const draft = useApi<ScheduleDraft>(props.modules.schedule || showHistory ? `${base}/schedule/draft` : null); const published = useApi<PublishedSchedule>(showHistory ? `${publicPath(props.eventId)}/schedule` : null); const boundary = useBoundary(draft.error);
  return <section className={styles.panel}><Identity props={props} role="行程管理人员" next="先保存和核对行程草稿，再发布给适用选手。" />{boundary.locked ? <AccessNotice eventId={props.eventId} /> : !props.modules.schedule ? <><p className={styles.empty}>行程功能已关闭，新增、导入、保存和发布暂停。已保存记录仍保留。</p><details className={styles.details} onToggle={event => setShowHistory(event.currentTarget.open)}><summary>查看已发布行程与保留草稿</summary>{showHistory && <><h3>已发布内容（当前身份可见范围）</h3><LoadState query={published}>{published.data && <ScheduleCards value={published.data} />}</LoadState><h3>主办方保留草稿</h3><LoadState query={draft}>{draft.data && <ReadOnlyScheduleDraft value={draft.data} />}</LoadState></>}</details></> : <LoadState query={draft}>{draft.data && <ScheduleEditor initial={draft.data} base={base} reload={draft.reload} lock={boundary.lock} />}</LoadState>}</section>;
}
function ReadOnlyScheduleDraft({ value }: { value: ScheduleDraft }) {
  return <><p className={styles.timezone}>时区 {value.timezone} · 草稿版本 {value.revision} · 正式发布版本 {value.publishedRevision ?? "尚未发布"}</p><p className={styles.muted}>以下是保留草稿，可能与已发布内容不同，仅当前行程管理人员可见。</p>{value.impact && <p className={styles.impact}>{value.impact}</p>}{value.items.length ? <ol className={styles.schedule}>{value.items.map(item => <li key={item.id} className={styles.card}><h4>{item.title}</h4><p className={styles.deadline}>{timeText(item.startsAt, value.timezone)} → {timeText(item.endsAt, value.timezone)}</p><p>{item.location}</p><p className={styles.muted}>范围：{item.audience === "all" ? "所有访客" : item.audience === "participants" ? "报名通过的选手" : `指定 ${item.userIds.length} 人`}</p></li>)}</ol> : <p className={styles.empty}>没有保留行程草稿。</p>}</>;
}
type ItemDraft = Omit<ScheduleItem, "id"> & { id?: string };
function ScheduleEditor({ initial, base, reload, lock }: { initial: ScheduleDraft; base: string; reload: () => Promise<void>; lock: () => void }) {
  const [items, setItems] = useState<ItemDraft[]>([...initial.items]); const [timezone, setTimezone] = useState(initial.timezone); const [impact, setImpact] = useState(initial.impact); const [csv, setCsv] = useState(""); const [preview, setPreview] = useState<ScheduleImportPreview | null>(null); const action = useAction(lock); const [published, setPublished] = useState<PublishedSchedule | null>(null);
  const [dirty, setDirty] = useState(false);
  useEffect(() => { if (!dirty) { setItems([...initial.items]); setTimezone(initial.timezone); setImpact(initial.impact); } }, [initial, dirty]);
  const editItem = (index: number, next: ItemDraft) => { setItems(current => current.map((item, at) => at === index ? next : item)); setDirty(true); setPublished(null); };
  return <><p className={styles.timezone}>当前赛事时区：{initial.timezone} · 草稿版本 {initial.revision} · 公开版本 {initial.publishedRevision ?? "尚未发布"}</p><p className={styles.muted}>保存草稿与正式发布分开。修改后先保存，再发布当前草稿版本。</p><DraftHint active={dirty || Boolean(csv.trim())} /><details className={styles.details}><summary>核对当前服务器草稿（版本 {initial.revision}）</summary><ReadOnlyScheduleDraft value={initial} /></details>
    <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${base}/schedule/draft`, { method: "PUT", body: { expectedRevision: initial.revision, timezone, items, impact } }), "行程草稿已保存，尚未发布。", async () => { setDirty(false); setPublished(null); setPreview(null); await reload(); }); }}><Field label="赛事时区" hint="必填。用时区名称，如 Asia/Shanghai；行程输入仍按北京时间保存，发布时按此时区展示，请核对换算。"><input required maxLength={100} value={timezone} onChange={event => { setTimezone(event.target.value); setDirty(true); }} placeholder="Asia/Shanghai" /></Field><Field label="本次变更影响或行动提醒" hint="首次行程可留空，修改已发布行程时必填。说明变化及下一步，例如“路演延后 30 分钟，请按新版时间到场”。"><textarea maxLength={1000} rows={2} value={impact} onChange={event => { setImpact(event.target.value); setDirty(true); }} /></Field>
      <div className={styles.stack}>{items.map((item, index) => <ScheduleItemForm key={item.id ?? `new-${index}`} item={item} index={index} onChange={next => editItem(index, next)} onRemove={() => { setItems(current => current.filter((_, at) => at !== index)); setDirty(true); }} onMove={direction => { setItems(current => { const copy = [...current]; [copy[index], copy[index + direction]] = [copy[index + direction], copy[index]]; return copy; }); setDirty(true); }} length={items.length} />)}</div><div className={styles.actions}><button type="button" onClick={() => { setItems(current => [...current, { id: operationKey(), title: "", startsAt: "", endsAt: "", location: "", audience: "all", userIds: [] }]); setDirty(true); }}>添加行程</button><button className={styles.primary} type="submit" disabled={action.busy || !dirty}>{action.busy ? "正在保存…" : "保存行程草稿"}</button></div></form>
    <div className={styles.publishBox}><p>发布会让符合适用范围的选手看到不可变的版本。请核对每项时间、地点和范围。</p><button type="button" className={styles.primary} disabled={action.busy || dirty || !initial.items.length} onClick={() => void action.run(async () => { const result = await api<PublishedSchedule>(`${base}/schedule/publish`, { method: "POST", body: { expectedRevision: initial.revision } }); setPublished(result); }, "行程当前版本已正式发布。", reload)}>发布已保存的行程</button>{dirty && <p className={styles.muted}>本地修改尚未保存，请先保存草稿。</p>}</div>{published && <ScheduleCards value={published} />}
    <details className={styles.details}><summary>从 CSV 导入行程</summary><p>先预览，再确认替换草稿；确认导入不会自动发布。表头为 title,startsAt,endsAt,location,audience,userIds。时间须含时区，如 2026-10-11T09:00:00+08:00；指定人员用分号分隔。</p><Field label="粘贴 CSV 文字" hint="选填的批量导入方式。粘贴带表头的 CSV，列顺序按上方说明；时间须含时区，audience 用 all、participants 或 users。"><textarea rows={7} value={csv} onChange={event => { setCsv(event.target.value); setPreview(null); }} /></Field><button type="button" disabled={action.busy || !csv.trim()} onClick={() => void action.run(async () => { setPreview(await api<ScheduleImportPreview>(`${base}/schedule/import/preview`, { method: "POST", body: { csv, expectedRevision: initial.revision, timezone, impact } })); }, "导入预览已生成，请逐项核对。")}>生成导入预览</button>{preview && <div className={styles.preview}><h4>预览 {preview.items.length} 项行程</h4><p>时区 {preview.timezone} · 预览截止 {dateText(preview.expiresAt)}</p>{preview.errors.length > 0 && <ul className={styles.error}>{preview.errors.map((error, at) => <li key={at}>第 {error.row} 行：{error.message}</li>)}</ul>}<ol className={styles.schedule}>{preview.items.map((item, at) => <li key={at}><strong>{item.title}</strong><p>{timeText(item.startsAt, preview.timezone)} → {timeText(item.endsAt, preview.timezone)} · {item.location} · {item.audience === "all" ? "公开" : item.audience === "participants" ? "报名选手" : `指定 ${item.userIds.length} 人`}</p></li>)}</ol><button type="button" disabled={action.busy || !!preview.errors.length || dirty} onClick={() => void action.run(() => api(`${base}/schedule/import/confirm`, { method: "POST", body: { previewId: preview.previewId, expectedRevision: initial.revision } }), "预览已确认并保存为行程草稿，请核对后发布。", async () => { setDirty(false); setCsv(""); setPreview(null); await reload(); })}>确认此预览，替换已保存草稿</button>{dirty && <p className={styles.muted}>请先保存本地行程修改，再生成并确认导入预览。</p>}</div>}</details><Feedback action={action} reload={reload} /></>;
}
function ScheduleItemForm({ item, index, length, onChange, onRemove, onMove }: { item: ItemDraft; index: number; length: number; onChange: (next: ItemDraft) => void; onRemove: () => void; onMove: (direction: -1 | 1) => void }) {
  const [userText, setUserText] = useState(item.userIds.join("\n"));
  return <fieldset className={styles.card}><legend>行程 {index + 1}</legend><Field label="名称" hint="必填。填写具体环节名称，例如签到、开发时间、路演；一项行程对应一个环节。"><input required maxLength={200} value={item.title} onChange={event => onChange({ ...item, title: event.target.value })} /></Field><div className={styles.twoColumns}><Field label="开始（北京时间 UTC+8）" hint="必填。选择该环节实际开始时间；输入按北京时间保存，即使上方赛事展示时区不同。"><input required type="datetime-local" value={localInput(item.startsAt)} onChange={event => onChange({ ...item, startsAt: event.target.value ? chinaInstant(event.target.value) : "" })} /></Field><Field label="结束（北京时间 UTC+8）" hint="必填。选择该环节结束时间，须晚于开始时间；仍按北京时间填写。"><input required type="datetime-local" value={localInput(item.endsAt)} onChange={event => onChange({ ...item, endsAt: event.target.value ? chinaInstant(event.target.value) : "" })} /></Field></div><Field label="地点" hint="必填。填写具体场馆、楼层或线上入口，例如“创新楼二层报告厅”；请确保目标选手能找到并进入。"><input required maxLength={500} value={item.location} onChange={event => onChange({ ...item, location: event.target.value })} /></Field><Field label="适用范围" hint="所有访客是公开行程；报名通过的选手只对本场入选人员；指定选手只向下方账号开放。"><select value={item.audience} onChange={event => { setUserText(""); onChange({ ...item, audience: event.target.value as ScheduleItem["audience"], userIds: [] }); }}><option value="all">所有访客</option><option value="participants">报名通过的选手</option><option value="users">指定选手</option></select></Field>{item.audience === "users" && <Field label="指定选手的账号编号（一行一人）" hint="选指定选手时需填写。复制本场报名名单中的本站账号编号，每行一人；不要用姓名或邮箱代替。"><textarea value={userText} onChange={event => { setUserText(event.target.value); onChange({ ...item, userIds: event.target.value.split(/\r?\n/).map(value => value.trim()).filter(Boolean) }); }} /></Field>}<p className={styles.muted}>输入按北京时间保存；发布后按赛事时区展示，请核对换算后的日期。</p><div className={styles.actions}><button type="button" disabled={index === 0} onClick={() => onMove(-1)}>上移</button><button type="button" disabled={index === length - 1} onClick={() => onMove(1)}>下移</button><button type="button" onClick={onRemove}>移除此行</button></div></fieldset>;
}

export function OwnEventServices(props: EventCommunicationProps) { return <OwnServicesInner key={props.eventId} {...props} />; }
function OwnServicesInner(props: EventCommunicationProps) {
  const base = publicPath(props.eventId); const enabled = props.modules.accommodation || props.modules.mealVouchers; const [showHistory, setShowHistory] = useState(false); const [showIcebreakerHistory, setShowIcebreakerHistory] = useState(false);
  const services = useApi<OwnServicesSnapshot>(enabled || showHistory ? `${base}/my-services` : null); const icebreakers = useApi<IcebreakerList>(props.modules.icebreaking || showIcebreakerHistory ? `${base}/icebreakers` : null);
  const boundary = useBoundary(services.error, icebreakers.error);
  return <section className={styles.panel}><Identity props={props} role="本人现场服务" next="核对自己的住宿和餐券；破冰活动按个人意愿参加。" />{boundary.locked ? <AccessNotice eventId={props.eventId} /> : <>
    {(!props.modules.accommodation || !props.modules.mealVouchers) && <details className={styles.details} onToggle={event => setShowHistory(event.currentTarget.open)}><summary>查看已关闭功能的本人历史安排</summary><p>关闭功能后仍保留已确认的住宿与餐券记录，新操作暂停。展开后只读取你在本赛事的历史。</p></details>}
    {(enabled || showHistory) && <LoadState query={services}>{services.data && <>
      {(props.modules.accommodation || showHistory) && <section className={styles.section}><h3>{props.modules.accommodation && services.data.modules.accommodation ? "我的住宿" : "我的住宿历史"}</h3>{services.data.accommodation ? <AccommodationCard value={services.data.accommodation} /> : <p className={styles.empty}>主办方尚未给你确认住宿安排。需要帮助时，向本赛事主办方发送私人求助。</p>}<a href={`${base}/help`}>询问我的住宿安排</a></section>}
      {(props.modules.mealVouchers || showHistory) && <section className={styles.section}><h3>{props.modules.mealVouchers && services.data.modules.mealVouchers ? "我的餐券" : "我的餐券历史"}</h3><p className={styles.muted}>向本赛事核销人员出示券编号，可人工核销。凭证只由主办方安全交付，不会出现在券列表中。</p>{services.data.vouchers.length ? services.data.vouchers.map(voucher => <VoucherCard key={voucher.id} value={voucher} />) : <p className={styles.empty}>主办方还没有给你发放餐券。</p>}</section>}
    </>}</LoadState>}
    {props.modules.icebreaking && <section className={styles.section}><h3>自愿破冰活动</h3><p className={styles.muted}>参加或婉拒均不影响报名与参赛资格。分组由工作人员按实际意愿安排。</p><LoadState query={icebreakers}>{icebreakers.data?.activities.length ? icebreakers.data.activities.map(activity => <OwnIcebreaker key={activity.id} activity={activity} base={base} reload={icebreakers.reload} lock={boundary.lock} readOnly={!icebreakers.data?.enabled} />) : <p className={styles.empty}>主办方还没有安排破冰活动。</p>}</LoadState></section>}
    {!props.modules.icebreaking && <details className={styles.details} onToggle={event => setShowIcebreakerHistory(event.currentTarget.open)}><summary>查看本人的破冰活动与分组历史</summary><p>功能关闭期间仅查看原有选择和分组，不新增参加、婉拒或分组。</p>{showIcebreakerHistory && <LoadState query={icebreakers}>{icebreakers.data?.activities.length ? icebreakers.data.activities.map(activity => <OwnIcebreaker key={activity.id} activity={activity} base={base} reload={icebreakers.reload} lock={boundary.lock} readOnly />) : <p className={styles.empty}>本赛事没有保留的本人破冰记录。</p>}</LoadState>}</details>}
    {!enabled && !props.modules.icebreaking && <p className={styles.empty}>这场赛事暂未启用现场服务，请查看官方通知。</p>}
  </>}</section>;
}
function AccommodationCard({ value }: { value: AccommodationAssignment }) {
  return <article className={styles.card}><h4>{value.location}</h4><p>房间：{value.room}</p><p className={styles.deadline}>入住 {dateText(value.checkIn)}<br />退房 {dateText(value.checkOut)}</p>{value.note && <p className={styles.pre}>{value.note}</p>}<p className={styles.muted}>安排版本 {value.revision} · 最后确认 {dateText(value.updatedAt)}</p></article>;
}
function VoucherCard({ value, children }: { value: MealVoucher; children?: ReactNode }) {
  return <article className={styles.card}><div className={styles.cardHead}><h4>{value.name}</h4><span className={styles.badge}>{voucherState[value.state]}</span></div><p><strong>剩余 {value.remainingUses} / {value.totalUses} 次</strong></p><p className={styles.deadline}>有效期至 {dateText(value.expiresAt)}</p><p className={styles.muted}>券编号：<span className={styles.identifier}>{value.id}</span></p>{children}</article>;
}
function OwnIcebreaker({ activity, base, reload, lock, readOnly = false }: { activity: IcebreakerActivity; base: string; reload: () => Promise<void>; lock: () => void; readOnly?: boolean }) {
  const action = useAction(lock);
  if (readOnly) return <article className={styles.card}><h4>{activity.title}</h4><p className={styles.pre}>{activity.description}</p><p className={styles.deadline}>{dateText(activity.startsAt)} · {activity.location}</p><p>本人原有选择：{activity.ownChoice === "join" ? "愿意参加" : activity.ownChoice === "decline" ? "婉拒" : "尚未选择"}</p>{activity.ownGroup && <p className={styles.impact}>本人原分组：<strong>{activity.ownGroup.title}</strong> · 版本 {activity.ownGroup.revision}</p>}<p className={styles.muted}>当前为保留历史，活动功能已关闭。</p></article>;
  return <article className={styles.card}><div className={styles.cardHead}><h4>{activity.title}</h4><span className={styles.badge}>{activity.ownChoice === "join" ? "你愿意参加" : activity.ownChoice === "decline" ? "你已婉拒" : "尚未选择"}</span></div><p className={styles.pre}>{activity.description}</p><p className={styles.deadline}>{dateText(activity.startsAt)} · {activity.location}</p>{activity.ownGroup && <p className={styles.impact}>你被安排到：<strong>{activity.ownGroup.title}</strong> · 分组版本 {activity.ownGroup.revision}</p>}<div className={styles.actions}><button className={styles.primary} type="button" disabled={action.busy || activity.ownChoice === "join"} onClick={() => void action.run(() => api(`${base}/icebreakers/${encodeURIComponent(activity.id)}/respond`, { method: "POST", body: { choice: "join" } }), "已记录你愿意参加，分组安排请留意本页。", reload)}>我愿意参加</button><button type="button" disabled={action.busy || activity.ownChoice === "decline"} onClick={() => void action.run(() => api(`${base}/icebreakers/${encodeURIComponent(activity.id)}/respond`, { method: "POST", body: { choice: "decline" } }), "已记录你的选择，不影响参赛资格。", reload)}>这次不参加</button></div><Feedback action={action} reload={reload} /></article>;
}

export function LogisticsManager(props: LogisticsManagerProps) { return <LogisticsManagerInner key={props.eventId} {...props} />; }
function LogisticsManagerInner(props: LogisticsManagerProps) {
  const base = staffPath(props.eventId); const [showHistory, setShowHistory] = useState(false);
  const accommodation = useApi<AccommodationAssignment[]>(props.modules.accommodation || showHistory ? `${base}/accommodation-assignments` : null);
  const types = useApi<VoucherType[]>(props.modules.mealVouchers ? `${base}/meal-voucher-types` : null);
  const vouchers = useApi<MealVoucher[]>(props.modules.mealVouchers || showHistory ? `${base}/meal-vouchers` : null);
  const icebreakers = useApi<IcebreakerList>(props.modules.icebreaking || showHistory ? `${base}/icebreakers` : null);
  const boundary = useBoundary(accommodation.error, types.error, vouchers.error, icebreakers.error);
  return <section className={styles.panel}><Identity props={props} role="本赛事现场服务人员" next="确认个人住宿安排、发放餐券或核销当前赛事的券。" />{boundary.locked ? <AccessNotice eventId={props.eventId} /> : <>
    {props.modules.mealVouchers && <section className={styles.section}><h3>核销餐券</h3><VoucherRedemption base={base} reload={vouchers.reload} lock={boundary.lock} /></section>}
    {props.modules.accommodation && <section className={styles.section}><h3>住宿安排</h3><p className={styles.muted}>仅本赛事有后勤权限的工作人员可管理，选手只能看到自己的安排。填写账号编号即可，不收集证件和电话。</p><LoadState query={accommodation}>{accommodation.data && <AccommodationManager values={accommodation.data} participants={props.participants} base={base} reload={accommodation.reload} lock={boundary.lock} />}</LoadState></section>}
    {props.modules.mealVouchers && <section className={styles.section}><h3>发放餐券</h3><LoadState query={types}>{types.data && <VoucherIssue values={types.data} participants={props.participants} base={base} reload={vouchers.reload} lock={boundary.lock} />}</LoadState><details className={styles.details}><summary>增加餐券类型</summary><VoucherTypeForm base={base} reload={types.reload} lock={boundary.lock} /></details><details className={styles.details}><summary>查看已发餐券和更正发放</summary><p className={styles.muted}>这里只显示券记录，不显示凭证。撤销后不能再核销。</p><LoadState query={vouchers}>{vouchers.data?.length ? vouchers.data.map(value => <ManagedVoucher key={value.id} value={value} base={base} reload={vouchers.reload} lock={boundary.lock} />) : <p className={styles.empty}>本赛事尚未发放餐券。</p>}</LoadState></details></section>}
    {props.modules.icebreaking && <section className={styles.section}><h3>自愿破冰与人工分组</h3>{icebreakers.data?.enabled && <IcebreakerForm base={base} reload={icebreakers.reload} lock={boundary.lock} />}<LoadState query={icebreakers}>{icebreakers.data?.activities.map(activity => <ManagedIcebreaker key={activity.id} activity={activity} participants={props.participants} base={base} reload={icebreakers.reload} lock={boundary.lock} readOnly={!icebreakers.data?.enabled} />)}</LoadState></section>}
    {(!props.modules.accommodation || !props.modules.mealVouchers || !props.modules.icebreaking) && <details className={styles.details} onToggle={event => setShowHistory(event.currentTarget.open)}><summary>查看已关闭功能的本赛事历史</summary><p>这里只读取保留记录。功能关闭期间不新增、更正、撤销或核销。</p>{showHistory && <>{!props.modules.accommodation && <section className={styles.section}><h3>住宿历史</h3><LoadState query={accommodation}>{accommodation.data?.length ? accommodation.data.map(value => <article key={value.id} className={styles.card}><p>账号：{props.participants?.find(person => person.userId === value.userId)?.label ?? value.userId}</p><AccommodationCard value={value} /></article>) : <p className={styles.empty}>本赛事没有保存住宿安排。</p>}</LoadState></section>}{!props.modules.mealVouchers && <section className={styles.section}><h3>餐券历史</h3><LoadState query={vouchers}>{vouchers.data?.length ? vouchers.data.map(value => <VoucherCard key={value.id} value={value}><p>本人账号：{props.participants?.find(person => person.userId === value.userId)?.label ?? value.userId}</p></VoucherCard>) : <p className={styles.empty}>本赛事没有保存餐券记录。</p>}</LoadState></section>}{!props.modules.icebreaking && <section className={styles.section}><h3>破冰选择与分组历史</h3><LoadState query={icebreakers}>{icebreakers.data?.activities.length ? icebreakers.data.activities.map(activity => <ManagedIcebreaker key={activity.id} activity={activity} participants={props.participants} base={base} reload={icebreakers.reload} lock={boundary.lock} readOnly />) : <p className={styles.empty}>本赛事没有保存破冰活动。</p>}</LoadState></section>}</>}</details>}
    {!props.modules.accommodation && !props.modules.mealVouchers && !props.modules.icebreaking && <p className={styles.empty}>本赛事没有启用现场服务。如需开启，请联系赛事负责人。</p>}
  </>}</section>;
}
function AccommodationManager({ values, participants, base, reload, lock }: { values: AccommodationAssignment[]; participants?: LogisticsManagerProps["participants"]; base: string; reload: () => Promise<void>; lock: () => void }) {
  const [editing, setEditing] = useState<AccommodationAssignment | null>(null); const [userId, setUserId] = useState(""); const [location, setLocation] = useState(""); const [room, setRoom] = useState(""); const [checkIn, setCheckIn] = useState(""); const [checkOut, setCheckOut] = useState(""); const [note, setNote] = useState(""); const [csv, setCsv] = useState(""); const [preview, setPreview] = useState<AccommodationImportPreview | null>(null); const action = useAction(lock);
  const listId = useId(); const currentAssignment = editing ? values.find(value => value.id === editing.id) ?? editing : null;
  const edit = (value: AccommodationAssignment) => { setEditing(value); setUserId(value.userId); setLocation(value.location); setRoom(value.room); setCheckIn(localInput(value.checkIn)); setCheckOut(localInput(value.checkOut)); setNote(value.note); };
  const reset = () => { setEditing(null); setUserId(""); setLocation(""); setRoom(""); setCheckIn(""); setCheckOut(""); setNote(""); };
  return <><form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${base}/accommodation-assignments`, { method: "POST", body: { userId, location, room, checkIn: chinaInstant(checkIn), checkOut: chinaInstant(checkOut), note, expectedRevision: currentAssignment?.revision ?? 0 } }), "住宿安排已确认，选手可查看自己的安排。", async () => { reset(); await reload(); }); }}><h4>{editing ? `更正安排 · 当前服务器版本 ${currentAssignment?.revision}` : "给一名选手确认住宿"}</h4>{editing && currentAssignment && currentAssignment.revision !== editing.revision && <div className={styles.preview}><h4>服务器已有更新，本地更正输入保留</h4><AccommodationCard value={currentAssignment} /><p>请核对上方最新安排与下方本地输入，再确认更正当前服务器版本。</p></div>}<ParticipantHint participants={participants} /><Field label="选手账号编号" hint="必填。从本场已通过报名名单选择或复制本站账号编号；姓名、电话和邮箱不能代替账号编号。"><input list={listId} required readOnly={!!editing} maxLength={200} value={userId} onChange={event => setUserId(event.target.value)} /></Field><ParticipantChoices participants={participants} listId={listId} /><div className={styles.twoColumns}><Field label="住宿地点" hint="必填。填写实际酒店或宿舍名称及地址，例如“某大学东区宿舍 2 号楼”。"><input required maxLength={200} value={location} onChange={event => setLocation(event.target.value)} /></Field><Field label="房间" hint="必填。填写分配给本人的房号或床位，例如“302 室 B 床”；只有本人和后勤人员可查看。"><input required maxLength={100} value={room} onChange={event => setRoom(event.target.value)} /></Field></div><div className={styles.twoColumns}><Field label="入住（北京时间 UTC+8）" hint="必填。选择允许入住的日期和时间，按北京时间填写。"><input required type="datetime-local" value={checkIn} onChange={event => setCheckIn(event.target.value)} /></Field><Field label="退房（北京时间 UTC+8）" hint="必填。选择最晚退房时间，须晚于入住，按北京时间填写。"><input required type="datetime-local" value={checkOut} onChange={event => setCheckOut(event.target.value)} /></Field></div><Field label="给本人的提醒（选填）" hint="选填。说明入住手续、前台联系或自备物品；仅本人和本场后勤人员可见，不应填写其他人的私人信息。"><textarea maxLength={1000} rows={2} value={note} onChange={event => setNote(event.target.value)} /></Field><div className={styles.actions}><button className={styles.primary} type="submit" disabled={action.busy}>{action.busy ? "正在确认…" : editing ? "确认更正此安排" : "确认住宿安排"}</button>{editing && <button type="button" disabled={action.busy} onClick={reset}>取消更正</button>}</div><DraftHint active={Boolean(userId || location || room || checkIn || checkOut || note || csv)} /></form><Feedback action={action} reload={reload} />
    <details className={styles.details}><summary>导入住宿 CSV，先预览再确认</summary><p>表头为 userId,location,room,checkIn,checkOut,note。日期含时区，如 2026-10-11T15:00:00+08:00。导入确认才会形成分配事实，预览不会改变选手安排。</p><Field label="粘贴 CSV" hint="选填的批量导入方式。粘贴带表头的住宿 CSV，账号用本场报名编号、日期含时区；先预览检查，确认后才会分配。"><textarea rows={6} value={csv} onChange={event => { setCsv(event.target.value); setPreview(null); }} /></Field><button type="button" disabled={action.busy || !csv.trim()} onClick={() => void action.run(async () => { setPreview(await api<AccommodationImportPreview>(`${base}/accommodation-import/preview`, { method: "POST", body: { csv } })); }, "住宿导入预览已生成，请检查每一行。")}>生成住宿预览</button>{preview && <div className={styles.preview}><h4>{preview.rows.length} 个安排待确认</h4><p>预览有效至 {dateText(preview.expiresAt)}</p>{preview.errors.length > 0 && <ul className={styles.error}>{preview.errors.map((error, at) => <li key={at}>第 {error.line} 行：{error.message}</li>)}</ul>}<ul className={styles.plainList}>{preview.rows.map(row => <li key={row.line}><strong>{row.userId}</strong> · {row.location} / {row.room}<p>{dateText(row.checkIn)} → {dateText(row.checkOut)} · {row.expectedRevision ? `更正版本 ${row.expectedRevision}` : "新增"}</p>{row.note && <p className={styles.pre}>{row.note}</p>}</li>)}</ul><button className={styles.primary} type="button" disabled={action.busy || !!preview.errors.length || !preview.rows.length} onClick={() => void action.run(() => api(`${base}/accommodation-import/confirm`, { method: "POST", body: { previewId: preview.id } }), "此预览中的住宿安排已确认。", async () => { setPreview(null); setCsv(""); await reload(); })}>确认全部预览安排</button></div>}</details>
    <details className={styles.details}><summary>查看已确认安排（{values.length}）</summary>{values.length ? values.map(value => <article className={styles.card} key={value.id}><p className={styles.muted}>本人：{participants?.find(person => person.userId === value.userId)?.label ?? value.userId}</p><AccommodationCard value={value} /><button type="button" disabled={action.busy} onClick={() => edit(value)}>更正此人的安排</button></article>) : <p className={styles.empty}>本赛事还没有确认住宿安排。</p>}</details>
  </>;
}
function VoucherTypeForm({ base, reload, lock }: { base: string; reload: () => Promise<void>; lock: () => void }) {
  const [name, setName] = useState(""); const [uses, setUses] = useState(1); const [expires, setExpires] = useState(""); const action = useAction(lock);
  return <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${base}/meal-voucher-types`, { method: "POST", body: { name, uses, expiresAt: chinaInstant(expires) } }), "餐券类型已创建，下一步可给选手发放。", async () => { setName(""); setUses(1); setExpires(""); await reload(); }); }}><Field label="餐券名称" hint="必填。写清日期及餐别，例如“比赛首日午餐”，让选手和核销人员都能辨认。"><input required maxLength={100} value={name} onChange={event => setName(event.target.value)} placeholder="如：比赛首日午餐" /></Field><Field label="每张可使用次数" hint="必填。填写每张券能领几次餐的整数，通常单餐填 1；核销一次扣一次。"><input required type="number" min={1} max={100} value={uses} onChange={event => setUses(Number(event.target.value))} /></Field><Field label="有效期至（北京时间 UTC+8）" hint="必填。选择这类餐券最后可领取的时间，须晚于当前时间；过期后不能使用。"><input required type="datetime-local" value={expires} onChange={event => setExpires(event.target.value)} /></Field><button type="submit" disabled={action.busy}>创建餐券类型</button><DraftHint active={Boolean(name || expires || uses !== 1)} /><Feedback action={action} reload={reload} /></form>;
}
function VoucherIssue({ values, participants, base, reload, lock }: { values: VoucherType[]; participants?: LogisticsManagerProps["participants"]; base: string; reload: () => Promise<void>; lock: () => void }) {
  const [userId, setUserId] = useState(""); const [typeId, setTypeId] = useState(values[0]?.id ?? ""); const [result, setResult] = useState<IssueVoucherResult | null>(null); const action = useAction(lock); const attempt = useRef<{ key: string; userId: string; typeId: string } | null>(null); const chosen = values.find(value => value.id === typeId);
  const listId = useId();
  useEffect(() => { if (!typeId && values.length) setTypeId(values[0].id); }, [values, typeId]);
  return <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(async () => { if (attempt.current && (attempt.current.userId !== userId || attempt.current.typeId !== typeId)) throw new Error("上次请求还没有确认。请用原输入重试并核对已发记录，再开始下一次发券。"); const request = attempt.current ?? { key: operationKey(), userId, typeId }; attempt.current = request; try { setResult(await api<IssueVoucherResult>(`${base}/meal-vouchers`, { method: "POST", body: { userId, typeId, idempotencyKey: request.key } })); } catch (reason) { if (reason instanceof ApiError && ([400, 404, 422].includes(reason.status) || (reason.status === 409 && ["VOUCHER_EXPIRED", "VERSION_CONFLICT", "EVENT_READ_ONLY", "EVENT_MODULE_DISABLED"].includes(reason.code)))) attempt.current = null; throw reason; } }, "发券操作已有明确回执，请核对下方结果。", reload); }}><ParticipantHint participants={participants} /><Field label="选手账号编号" hint="必填。从本场已通过报名名单选择或复制本站账号编号；姓名、电话和邮箱不能代替账号编号。"><input list={listId} required maxLength={200} value={userId} onChange={event => setUserId(event.target.value)} /></Field><ParticipantChoices participants={participants} listId={listId} /><Field label="餐券类型" hint="选择已创建的本场餐券，先核对餐别、次数和有效期；保存后向所选账号发放这一类券。"><select required value={typeId} onChange={event => setTypeId(event.target.value)}><option value="" disabled>选择本赛事餐券</option>{values.map(value => <option key={value.id} value={value.id}>{value.name} · 每张 {value.uses} 次</option>)}</select></Field>{chosen && <p className={styles.deadline}>有效期至 {dateText(chosen.expiresAt)}</p>}<button className={styles.primary} type="submit" disabled={action.busy || !values.length || !!result}>{action.busy ? "正在发放…" : result ? "本次发券已有回执" : "给此人发放餐券"}</button>{!values.length && <p className={styles.muted}>先在下面增加餐券类型，再发放。</p>}
    {result && <div className={styles.privateToken}><h4>{result.replayed ? "已找到原发券回执" : "餐券已发放"}</h4><p>{result.voucher.name} · 本人账号 {result.voucher.userId}</p><p>券编号：<span className={styles.identifier}>{result.voucher.id}</span></p>{result.token ? <><DraftHint active text="当前凭证仍在页面中。切换赛事或离开后会清除，请先安全交付本人。" /><p><strong>凭证只在本次结果中展示。</strong>请安全交给本人，避免公开或发给第三方二维码服务。</p><code className={styles.token}>{result.token}</code><button type="button" onClick={() => setResult(current => current ? { ...current, token: null } : null)}>已交付，清除页面凭证</button></> : <p>此回执不再返回凭证。现场可按券编号人工核销，并留下操作员记录。</p>}<button type="button" disabled={action.busy} onClick={() => { setResult(null); setUserId(""); attempt.current = null; }}>结束此操作，开始下一次发券</button></div>}{action.error && attempt.current && <button type="button" disabled={action.busy} onClick={() => { attempt.current = null; setResult(null); }}>已核对原记录，为当前输入开始新操作</button>}<DraftHint active={Boolean(userId && !result)} /><p className={styles.muted}>失败后输入与同一次操作编号保留。结果不明时，先查看已发记录，避免重复发券。</p><Feedback action={action} reload={reload} /></form>;
}
function VoucherRedemption({ base, reload, lock }: { base: string; reload: () => Promise<void>; lock: () => void }) {
  const [mode, setMode] = useState<"token" | "manual">("token"); const [target, setTarget] = useState(""); const [confirmed, setConfirmed] = useState(false); const [result, setResult] = useState<RedeemVoucherResult | null>(null); const action = useAction(lock); const attempt = useRef<{ key: string; mode: string; target: string } | null>(null);
  return <form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(async () => { if (!confirmed) throw new Error("请先确认本次领取，再核销一次。"); if (attempt.current && (attempt.current.mode !== mode || attempt.current.target !== target)) throw new Error("请先确认上次操作结果，再开始下一次核销。"); const request = attempt.current ?? { key: operationKey(), mode, target }; attempt.current = request; try { setResult(await api<RedeemVoucherResult>(`${base}/meal-vouchers/redeem`, { method: "POST", body: { ...(mode === "token" ? { token: target } : { voucherId: target }), idempotencyKey: request.key } })); } catch (reason) { if (reason instanceof ApiError && ([400, 404, 422].includes(reason.status) || (reason.status === 409 && ["VOUCHER_EXPIRED", "VOUCHER_REVOKED", "VOUCHER_EXHAUSTED", "VERSION_CONFLICT", "EVENT_READ_ONLY", "EVENT_MODULE_DISABLED"].includes(reason.code)))) attempt.current = null; throw reason; } }, "核销结果已确认，请查看回执。", reload); }}><Field label="核销方式" hint="有本人提供的凭证选凭证核销；无法提供凭证时按券编号人工核销。两种方式都会记录工作人员和领取次数。"><select value={mode} onChange={event => { setMode(event.target.value as "token" | "manual"); setConfirmed(false); }}><option value="token">输入本人提供的餐券凭证</option><option value="manual">按券编号人工核销</option></select></Field><Field label={mode === "token" ? "本赛事餐券凭证" : "本赛事券编号"} hint={mode === "token" ? "必填。粘贴领取人提供的本场完整餐券凭证；不要填写券名、账号或邮箱。" : "必填。复制本场已发记录中的券编号，先人工核对领取人及餐别；不要填写账号编号。"}><input required maxLength={mode === "token" ? 256 : 200} autoComplete="off" value={target} onChange={event => { setTarget(event.target.value); setConfirmed(false); }} /></Field><label className={styles.check}><input type="checkbox" checked={confirmed} onChange={event => setConfirmed(event.target.checked)} />我已核对当前赛事与领取人，确认本次领取餐食</label><button className={styles.primary} type="submit" disabled={action.busy || !confirmed || !!result}>{action.busy ? "正在核销…" : result ? "本次核销已有回执" : "确认核销 1 次"}</button>{result && <div className={styles.preview}><h4>{result.replayed ? "原核销回执" : "核销成功"}</h4><p>券编号：{result.receipt.voucherId} · 剩余 {result.receipt.remainingUses} 次</p><p>{dateText(result.receipt.redeemedAt)} · {result.receipt.mode === "manual" ? "人工核销" : "凭证核销"}</p><p className={styles.muted}>回执 {result.receipt.id} · 操作员 {result.receipt.operatorUserId}</p><button type="button" disabled={action.busy} onClick={() => { setTarget(""); setConfirmed(false); setResult(null); attempt.current = null; }}>清除输入，核销下一次领取</button></div>}{action.error && attempt.current && <button type="button" disabled={action.busy} onClick={() => { attempt.current = null; setResult(null); setTarget(""); setConfirmed(false); }}>已核对上次记录，改为新的核销目标</button>}<DraftHint active={Boolean(target && !result)} /><p className={styles.muted}>同一次操作重试会读取原回执，不会再次扣券。人工核销会留下操作员记录。</p><Feedback action={action} reload={reload} /></form>;
}
function ManagedVoucher({ value, base, reload, lock }: { value: MealVoucher; base: string; reload: () => Promise<void>; lock: () => void }) {
  const action = useAction(lock);
  return <VoucherCard value={value}><p className={styles.muted}>本人账号：{value.userId} · 发放于 {dateText(value.issuedAt)}</p>{value.state === "available" && <details className={styles.details}><summary>撤销此券</summary><p>确认是发错或需要作废的券后再撤销。已核销回执保留。</p><button type="button" disabled={action.busy} onClick={() => void action.run(() => api(`${base}/meal-vouchers/${encodeURIComponent(value.id)}/revoke`, { method: "POST", body: { expectedRevision: value.revision } }), "此券已撤销。", reload)}>确认撤销此券</button></details>}<Feedback action={action} reload={reload} /></VoucherCard>;
}
function IcebreakerForm({ base, reload, lock }: { base: string; reload: () => Promise<void>; lock: () => void }) {
  const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [startsAt, setStartsAt] = useState(""); const [location, setLocation] = useState(""); const action = useAction(lock);
  return <details className={styles.details}><summary>安排一个自愿活动</summary><form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${base}/icebreakers`, { method: "POST", body: { title, description, startsAt: chinaInstant(startsAt), location } }), "活动已建立，选手可以主动选择参加。", async () => { setTitle(""); setDescription(""); setStartsAt(""); setLocation(""); await reload(); }); }}><Field label="活动名称" hint="必填。填写破冰活动名称，例如“3 分钟项目互相介绍”。"><input required maxLength={200} value={title} onChange={event => setTitle(event.target.value)} /></Field><Field label="活动说明" hint="必填。写清活动怎么玩、多久、是否需要准备；选手自愿参加，不会自动分组。"><textarea required maxLength={2000} rows={3} value={description} onChange={event => setDescription(event.target.value)} /></Field><Field label="开始时间（北京时间 UTC+8）" hint="必填。填写活动开始的日期和时刻，按北京时间保存。"><input required type="datetime-local" value={startsAt} onChange={event => setStartsAt(event.target.value)} /></Field><Field label="地点" hint="必填。填写具体场馆、楼层或线上入口，例如“创新楼二层报告厅”；请确保目标选手能找到并进入。"><input required maxLength={500} value={location} onChange={event => setLocation(event.target.value)} /></Field><button type="submit" disabled={action.busy}>创建自愿活动</button><DraftHint active={Boolean(title || description || startsAt || location)} /><Feedback action={action} reload={reload} /></form></details>;
}
function ManagedIcebreaker({ activity, participants, base, reload, lock, readOnly = false }: { activity: IcebreakerActivity; participants?: LogisticsManagerProps["participants"]; base: string; reload: () => Promise<void>; lock: () => void; readOnly?: boolean }) {
  const [title, setTitle] = useState(""); const [userIds, setUserIds] = useState<string[]>([]); const action = useAction(lock); const joined = activity.responses?.filter(item => item.choice === "join") ?? [];
  if (readOnly) return <article className={styles.card}><h4>{activity.title}</h4><p className={styles.pre}>{activity.description}</p><p className={styles.deadline}>{dateText(activity.startsAt)} · {activity.location}</p><p>{joined.length} 人原选择参加 · {activity.responses?.filter(item => item.choice === "decline").length ?? 0} 人原选择婉拒</p>{activity.groups?.map(group => <div key={group.id} className={styles.preview}><strong>{group.title}</strong><p>{group.memberUserIds.length} 名成员 · 版本 {group.revision}</p><p>{group.memberUserIds.map(id => participants?.find(person => person.userId === id)?.label ?? id).join("、") || "当前为空组"}</p></div>)}<p className={styles.muted}>当前为保留历史，活动功能已关闭。新增活动与更正分组暂停。</p></article>;
  return <article className={styles.card}><h4>{activity.title}</h4><p className={styles.pre}>{activity.description}</p><p className={styles.deadline}>{dateText(activity.startsAt)} · {activity.location}</p><p>{joined.length} 人愿意参加 · {activity.responses?.filter(item => item.choice === "decline").length ?? 0} 人婉拒</p><details className={styles.details}><summary>人工安排分组</summary><p>只能安排报名通过且主动参加的选手。同名组将更正已有成员，保留历史版本。</p><form className={styles.form} onSubmit={event => { event.preventDefault(); void action.run(() => api(`${base}/icebreakers/${encodeURIComponent(activity.id)}/groups`, { method: "POST", body: { title, userIds, expectedRevision: activity.revision } }), "分组记录已确认，成员可查看自己的组。", async () => { setTitle(""); setUserIds([]); await reload(); }); }}><Field label="组名" hint="必填。填写便于辨认的活动小组名，例如“产品交流组”；同名组会更正原成员，清空选择会清空该组。"><input required maxLength={100} value={title} onChange={event => setTitle(event.target.value)} /></Field><fieldset className={styles.choices}><legend>选择主动参加的选手</legend><p className={styles.muted}>勾选要分到此组的人；只列本场报名通过且愿意参加者。更正同名组时，未勾选者会从该组移除。</p>{joined.length ? joined.map(item => <label className={styles.check} key={item.userId}><input type="checkbox" checked={userIds.includes(item.userId)} onChange={event => setUserIds(current => event.target.checked ? [...current, item.userId] : current.filter(id => id !== item.userId))} />{participants?.find(person => person.userId === item.userId)?.label ?? `账号 ${item.userId}`}</label>) : <p>还没有人主动参加，请等待选手选择。</p>}</fieldset><button type="submit" disabled={action.busy}>{userIds.length ? "确认人工分组" : "确认清空此组成员"}</button><DraftHint active={Boolean(title || userIds.length)} /></form>{activity.groups?.map(group => <div key={group.id} className={styles.preview}><strong>{group.title}</strong><p>{group.memberUserIds.length} 名成员 · 版本 {group.revision}</p><p className={styles.identifier}>{group.memberUserIds.map(id => participants?.find(person => person.userId === id)?.label ?? id).join("、") || "当前为空组"}</p><button type="button" disabled={action.busy} onClick={() => { setTitle(group.title); setUserIds([...group.memberUserIds]); }}>更正此组</button></div>)}</details><Feedback action={action} reload={reload} /></article>;
}
